        readiness: {
            type: String,
            enum: ['unknown', 'ready_now', 'buy_later'],
            default: 'unknown'
        },
        requestedQuantity: Number,
        requestedPackageLabel: String,
        desiredPurchaseTiming: String,
        followUpAt: Date,
        readyConfirmedAt: Date,
        buyLaterDetectedAt: Date,
        lastReadinessQuestionAt: Date
    },
    whatsappNotified: {
        type: Boolean,
        default: false
    },
    whatsappFunnel: {
        audio1SentAt: Date,
        audio1File: String,
        audio2SentAt: Date,
        addressConfirmSentAt: Date,
        offerSentAt: Date,
        lockUntil: Date
    },
    tracking: {
        measurementVersion: Number,
        renderedBranch: String,
        branchIdentity: String,
        browserPixelId: String,
        checkoutEventId: String,
        country: String,
        productKey: String,
        productName: String,
        product: String,
        funnel: String,
        contentName: String,
        contentIds: [String],
        fbclid: String,
        fbc: String,
        fbp: String,
        ext_id: String, // External ID (for affiliates/tracking)
        external_id: String,
        utm_source: String,
        utm_medium: String,
        utm_campaign: String,
        utm_content: String,
        utm_term: String,
        campaign_id: String,
        adset_id: String,
        ad_id: String,
        placement: String,
        attributionCapturedAt: Date,
        sourceUrl: String,
        ip: String,
        userAgent: String,
        clientContextSource: String,
