import express from 'express';
import Order from '../models/Order.js';
import Shipment from '../models/Shipment.js';
import Message from '../models/Message.js';
import { authMiddleware, isPanelAuthDisabled } from '../middleware/auth.js';
import { sendPurchaseEventForOrder } from '../services/metaConversionsService.js';
import { syncOrderToOnlineAdminPanel } from '../services/adminPanelStatusService.js';
import {
    getCustomerPurchaseEligibility,
    PREPAID_REQUIRED_MESSAGE
} from '../services/customerPurchaseEligibilityService.js';
import {
    assertNoActiveDuplicateOrder,
    getOrderDuplicateGuard
} from '../services/orderDuplicateGuardService.js';
import {
    ecuadorPackageLabel,
    ecuadorProductMetadata,
    resolveEcuadorProductInfo,
    validateExplicitEcuadorProductSelection
} from '../services/ecuadorProductService.js';
import {
    assertCustomerOrderDataReady,
    resolveCustomerDataDraft
} from '../services/customerDataResolutionService.js';
import {
    buildDeliveredRepurchaseOrderId,
    repurchaseOrderCreationPolicy
} from '../services/ecDeliveredRepurchaseService.js';
import { persistManualPanelStatusV139 } from '../services/ecDropiStatusPostSaleV139Service.js';
import { ecPanelStatusAuthenticatedActionV177 } from '../services/ecBotCoreRuntimeIntegrationV78Service.js';
import { manualHistoricalRequestV203, ecPhoneV203, manualHistoricalMetadataV203, manualShipmentTerminalReviewV203 } from '../services/ecHistoricalOrderStatusV203Service.js';
import { readEcLegacyHistoryV203 } from '../services/ecHistoricalLegacyV203Service.js';

const router = express.Router();

const normalizeOrderStatus = (status) => {
    const value = String(status || '').trim().toLowerCase().replace(/-/g, '_');
    const aliases = {
        confirmado: 'confirmed',
        pedido_enviado: 'processing',
        enviado: 'processing',
        entregue: 'delivered',
        recompra: 'delivered',
        cancelado: 'cancelled',
        devolvido: 'returned'
    };
    return aliases[value] || value;
};

const digitsOnly = (value) => String(value || '').replace(/\D/g, '');

const VALID_PACKAGE_QUANTITIES = new Set([1, 2, 3, 6]);

const normalizePackageQuantity = (value) => {
    const parsed = Number.parseInt(String(value ?? '').trim(), 10);
    return VALID_PACKAGE_QUANTITIES.has(parsed) ? parsed : 0;
};

const orderHasValidPackage = (order) => normalizePackageQuantity(order?.package?.quantity || order?.package?.id) > 0;

const isEcuadorCountry = (country = '') => String(country || '').trim().toUpperCase() === 'EC';

const productSelectionInput = ({
    productKey = '',
    productName = '',
    product = '',
    packageLabel = '',
    tracking = {}
} = {}) => ({
    productKey,
    identifiers: [
        tracking?.productKey,
        tracking?.productName,
        tracking?.contentName,
        productName,
        product,
        packageLabel
    ]
});

const hasExplicitProductSelectionInput = (input = {}) => {
    const selection = productSelectionInput(input);
    return Boolean(
        String(selection.productKey || '').trim()
        || selection.identifiers.some((value) => String(value || '').trim())
    );
};

const strictEcuadorProductSelection = (input = {}) => (
    validateExplicitEcuadorProductSelection(productSelectionInput(input))
);

const productInfoFromOrderRequest = ({ country = 'EC', ...input } = {}) => (
    isEcuadorCountry(country) ? strictEcuadorProductSelection(input) : null
);

const sendExplicitProductError = (res, selection = {}) => res.status(400).json({
    error: 'Produto EC explicito obrigatorio: tex_ultra_ec, nitrix_ec ou vit_power_ec.',
    reason: selection.reason || 'missing_explicit_product'
});

const isLocalPanelAuthBypassRequest = (req = {}) => {
    const host = String(req.hostname || req.headers?.host || '').split(':')[0];
    const ip = String(req.ip || req.socket?.remoteAddress || '');
    return ['localhost', '127.0.0.1', '::1'].includes(host)
        || /^(192\.168\.|10\.|172\.(1[6-9]|2\d|3[01])\.)/.test(host)
        || ip === '127.0.0.1'
        || ip === '::1'
        || ip === '::ffff:127.0.0.1';
};

const optionalPanelAuth = (req, res, next) => {
    const hasBearer = String(req.headers?.authorization || '').startsWith('Bearer ');
    if (isLocalPanelAuthBypassRequest(req)) return authMiddleware(req, res, next);
    if (!hasBearer || isPanelAuthDisabled(req)) return next();
    return authMiddleware(req, res, next);
};

const productAwarePackageLabel = ({ country = 'EC', productInfo = null, quantity = 0, fallback = '' } = {}) => (
    isEcuadorCountry(country) && productInfo
        ? ecuadorPackageLabel(productInfo, quantity)
        : (fallback || `Package ${quantity}`)
);

const productTrackingMetadata = (productInfo = null) => (
    productInfo ? ecuadorProductMetadata(productInfo) : {}
);

const isBrazilTestOnly = ({ phone = '', country = '' } = {}) => {
    const normalizedCountry = String(country || '').trim().toUpperCase();
    const phoneDigits = digitsOnly(phone);
    return normalizedCountry === 'BR' || phoneDigits.startsWith('55');
};

const appendAuditNote = (current = '', note = '') => {
    const prefix = current ? `${String(current).trim()}\n` : '';
    return `${prefix}[${new Date().toISOString()}] ${note}`.trim();
};

const resolveOrderCustomerData = ({
    country = 'EC',
    customer = {},
    delivery = {},
    previousResolution = null,
    source = 'structured_form'
} = {}) => resolveCustomerDataDraft({
    draft: {
        country,
        name: customer?.name || '',
        phone: customer?.phone || '',
        city: customer?.city || '',
        province: customer?.province || '',
        address: customer?.address || '',
        reference: customer?.reference || '',
        deliveryMode: delivery?.mode || customer?.deliveryMode || '',
        agencyId: delivery?.agencyId || customer?.agencyId || '',
        agencyName: delivery?.agencyName || customer?.agencyName || ''
    },
    previousResolution,
    conversationPhone: '',
    source
});

const applyCustomerDataResolutionToOrder = (order, result) => {
    const draft = result.draft;
    order.customer = {
        ...(order.customer?.toObject?.() || order.customer || {}),
        name: draft.name || '',
        phone: draft.phone || '',
        city: draft.city || '',
        province: draft.province || '',
        address: draft.address || '',
        reference: draft.reference || ''
    };
    order.delivery = {
        mode: draft.deliveryMode || '',
        agencyId: draft.agencyId || '',
        agencyName: draft.agencyName || ''
    };
    order.customerDataResolution = result.resolution;
    return order;
};

const sendCustomerDataResolutionError = (res, errorOrResolution) => {
    const resolution = errorOrResolution?.resolution || errorOrResolution || {};
    return res.status(422).json({
