                ...(order.delivery?.toObject?.() || order.delivery || {}),
                ...(typeof delivery.mode === 'string' ? { mode: delivery.mode.trim() } : {}),
                ...(typeof delivery.agencyId === 'string' ? { agencyId: delivery.agencyId.trim() } : {}),
                ...(typeof delivery.agencyName === 'string' ? { agencyName: delivery.agencyName.trim() } : {})
            };
        }

        // Update package if provided
        if (packageId !== undefined) {
            const normalizedQuantity = normalizePackageQuantity(packageId);
            order.package.id = normalizedQuantity;
            order.package.label = normalizedQuantity ? (packageLabel || `Package ${normalizedQuantity}`) : '';
            order.package.quantity = normalizedQuantity;
        }

        // Update total if provided
        if (total !== undefined) {
            order.total = total;
        }

        if (tracking) {
            order.tracking = order.tracking || {};
            for (const [k, v] of Object.entries(tracking)) {
                if (v !== undefined && v !== null && String(v).length > 0) {
                    order.tracking[k] = v;
                }
            }
            // Always refresh IP/UA if missing
            if (!order.tracking.ip) order.tracking.ip = req.ip;
            if (!order.tracking.userAgent) order.tracking.userAgent = req.get('user-agent') || '';
        }
        if (requestedProductSelection?.ok) {
            order.tracking = {
                ...(order.tracking || {}),
                ...productTrackingMetadata(requestedProductSelection.product)
            };
            const quantity = normalizePackageQuantity(order.package?.quantity || order.package?.id);
            if (quantity) order.package.label = ecuadorPackageLabel(requestedProductSelection.product, quantity);
        }

        if (purchaseIntent) {
            order.purchaseIntent = {
                ...(order.purchaseIntent || {}),
                ...purchaseIntent
            };
        }

        applyCustomerDataResolutionToOrder(order, resolveOrderCustomerData({
            country: order.country,
            customer: order.customer,
            delivery: order.delivery,
            previousResolution: order.customerDataResolution?.toObject?.() || order.customerDataResolution || null,
            source: 'structured_form'
        }));

        await order.save();

        res.json({
            success: true,
            orderId: order.orderId,
            message: 'Draft updated'
        });
    } catch (error) {
        console.error('Update draft error:', error);
        res.status(500).json({ error: 'Failed to update draft' });
    }
});

// POST /api/orders/draft/:id/submit - Convert draft to pending (public)
// Called on final form submit
router.post('/draft/:id/submit', async (req, res) => {
    try {
        const {
            purchaseIntent,
            productKey,
            productName,
            product,
            tracking
        } = req.body || {};
        const order = await Order.findOne({ orderId: req.params.id, status: 'draft' });

        if (!order) {
            return res.status(404).json({ error: 'Draft not found' });
        }

        if (!order.package.id || order.total <= 0) {
            return res.status(400).json({ error: 'Package not selected' });
        }

        if (isBrazilTestOnly({ phone: order.customer?.phone, country: order.country })) {
            return sendBrazilTestOnlyError(res);
        }

        let submittedProduct = null;
        if (isEcuadorCountry(order.country)) {
            const requestedProductInput = { productKey, productName, product, tracking };
            const storedProductInput = {
                productKey: order.tracking?.productKey,
                productName: order.tracking?.productName,
                tracking: order.tracking || {},
                packageLabel: order.package?.label || ''
            };
            const productSelection = hasExplicitProductSelectionInput(requestedProductInput)
                ? strictEcuadorProductSelection(requestedProductInput)
                : strictEcuadorProductSelection(storedProductInput);
            if (!productSelection.ok) return sendExplicitProductError(res, productSelection);
            submittedProduct = productSelection.product;
        }

        const resolvedCustomerData = resolveOrderCustomerData({
            country: order.country,
            customer: order.customer,
            delivery: order.delivery,
            previousResolution: order.customerDataResolution?.toObject?.() || order.customerDataResolution || null,
            source: 'structured_form'
        });
        applyCustomerDataResolutionToOrder(order, resolvedCustomerData);
        if (resolvedCustomerData.resolution.orderDataReady !== true) {
            await order.save();
            return sendCustomerDataResolutionError(res, resolvedCustomerData.resolution);
        }

        try {
            await assertNoActiveDuplicateOrder({
                phone: order.customer.phone,
                country: order.country,
                currentOrderId: order.orderId
            });
            await assertCashOnDeliveryEligible({
                phone: order.customer.phone,
                country: order.country
            });
        } catch (eligibilityError) {
            if (eligibilityError.code === 'active_duplicate_order') {
                return sendDuplicateOrderError(res, eligibilityError);
            }
            return sendEligibilityError(res, eligibilityError);
        }

        // Convert to pending
        order.status = 'pending';
        order.lastInteractionAt = new Date();
        if (purchaseIntent) {
            order.purchaseIntent = {
                ...(order.purchaseIntent || {}),
                ...purchaseIntent
            };
        }

        // Ensure we store IP/UA for later CAPI usage
        order.tracking = order.tracking || {};
        if (!order.tracking.ip) order.tracking.ip = req.ip;
        if (!order.tracking.userAgent) order.tracking.userAgent = req.get('user-agent') || '';
        if (submittedProduct) {
            order.tracking = {
                ...order.tracking,
                ...productTrackingMetadata(submittedProduct)
            };
            order.package.label = ecuadorPackageLabel(submittedProduct, order.package.quantity || order.package.id);
        }

        await order.save();

        console.log(`✅ Draft submitted: ${order.orderId} -> pending`);

        res.json({
            success: true,
            orderId: order.orderId,
            message: 'Order submitted successfully'
        });
    } catch (error) {
        console.error('Submit draft error:', error);
        res.status(500).json({ error: 'Failed to submit order' });
    }
});

