// POST /api/orders - Create order directly (public - from checkout)
router.post('/', optionalPanelAuth, async (req, res) => {
    try {
        const { country, customer, delivery, packageId, packageLabel, total, currency, source = 'checkout', tracking, purchaseIntent, status, notes, productKey, productName, product, previousOrderId } = req.body;

        // Validation
        if (!country || !customer || !packageId || !total) {
            return res.status(400).json({ error: 'Missing required fields' });
        }
        const normalizedPackageQuantity = normalizePackageQuantity(packageId);
        if (!normalizedPackageQuantity) {
            return res.status(400).json({ error: 'Quantidade valida obrigatoria: 1, 2, 3 ou 6 frascos.' });
        }

        if (isBrazilTestOnly({ phone: customer.phone, country })) {
            return sendBrazilTestOnlyError(res);
        }

        const requestedStatus = normalizeOrderStatus(status);
        const allowedPublicInitialStatuses = new Set(['draft', 'pending']);
        const allowedAuthenticatedInitialStatuses = new Set([
            'draft',
            'pending',
            'confirmed',
            'processing',
            'shipped',
            'delivered',
            'cancelled',
            'returned'
        ]);
        const allowedInitialStatuses = req.user
            ? allowedAuthenticatedInitialStatuses
            : allowedPublicInitialStatuses;
        if (requestedStatus && !allowedInitialStatuses.has(requestedStatus)) {
            return res.status(400).json({
                error: 'public_order_status_not_allowed',
                message: 'Pedido publico pode iniciar somente como draft ou pending.'
            });
        }
        const initialStatus = requestedStatus || 'pending';
        const productSelection = productInfoFromOrderRequest({
            country,
            productKey,
            productName,
            product,
            packageLabel,
            tracking
        });
        if (productSelection && !productSelection.ok) {
            return sendExplicitProductError(res, productSelection);
        }
        const productInfo = productSelection?.product || null;
        const resolvedCustomerData = resolveOrderCustomerData({
            country,
            customer,
            delivery,
            source: 'structured_form'
        });
        if (initialStatus !== 'draft' && resolvedCustomerData.resolution.orderDataReady !== true) {
            return sendCustomerDataResolutionError(res, resolvedCustomerData.resolution);
        }

        const normalizedPreviousOrderId = String(previousOrderId || '').trim().slice(0, 100);
        let repurchaseContext = null;
        if (normalizedPreviousOrderId) {
            const previousOrder = await Order.findOne({
                country,
                orderId: normalizedPreviousOrderId
            }).lean().catch(() => null);
            const previousShipment = previousOrder
                ? await Shipment.findOne({ country, orderId: normalizedPreviousOrderId })
                    .sort({ 'logistics.lastStatusAt': -1, updatedAt: -1, createdAt: -1 })
                    .lean()
                    .catch(() => null)
                : null;
            repurchaseContext = repurchaseOrderCreationPolicy({
                authenticated: Boolean(req.user),
                previousOrder,
                previousShipment,
                newCustomerPhone: resolvedCustomerData.draft.phone
            });
            if (!repurchaseContext.allowed) {
                return res.status(repurchaseContext.statusCode || 409).json({
                    error: repurchaseContext.reason,
                    message: repurchaseContext.reason === 'repurchase_requires_panel_auth'
                        ? 'Recompra exige confirmação autenticada no painel.'
                        : 'O pedido anterior precisa estar entregue e pertencer ao mesmo cliente.'
                });
            }
        }

        try {
            await assertNoActiveDuplicateOrder({
                phone: resolvedCustomerData.draft.phone,
                country
            });
            await assertCashOnDeliveryEligible({
                phone: resolvedCustomerData.draft.phone,
                country
            });
        } catch (eligibilityError) {
            if (eligibilityError.code === 'active_duplicate_order') {
                return sendDuplicateOrderError(res, eligibilityError);
            }
            return sendEligibilityError(res, eligibilityError);
        }

        // Determine currency from country
        const orderCurrency = currency || 'USD';
        const productTracking = productTrackingMetadata(productInfo);

        // Create order
        const order = new Order({
            orderId: repurchaseContext ? buildDeliveredRepurchaseOrderId() : undefined,
            country,
            customer: {
                name: resolvedCustomerData.draft.name,
                phone: resolvedCustomerData.draft.phone,
                address: resolvedCustomerData.draft.address,
                reference: resolvedCustomerData.draft.reference,
                city: resolvedCustomerData.draft.city,
                province: resolvedCustomerData.draft.province
            },
            delivery: {
                mode: resolvedCustomerData.draft.deliveryMode,
                agencyId: resolvedCustomerData.draft.agencyId,
                agencyName: resolvedCustomerData.draft.agencyName
            },
            customerDataResolution: resolvedCustomerData.resolution,
            package: {
                id: normalizedPackageQuantity,
                label: productAwarePackageLabel({
                    country,
                    productInfo,
                    quantity: normalizedPackageQuantity,
                    fallback: packageLabel
                }),
                quantity: normalizedPackageQuantity
            },
            total,
            currency: orderCurrency,
            source,
            status: initialStatus,
            entryReason: repurchaseContext?.entryReason || 'new_purchase',
            previousOrderId: repurchaseContext?.previousOrderId || '',
            previousDeliveredAt: repurchaseContext?.previousDeliveredAt || null,
            notes: typeof notes === 'string' ? notes : '',
            purchaseIntent: purchaseIntent || {},
            tracking: {
                ...(tracking || {}),
                ...productTracking,
                ip: req.ip,
                userAgent: req.get('user-agent') || ''
            }
        });

        await order.save();
        let purchase = null;
        if (initialStatus === 'confirmed' && req.user) {
            purchase = await markPurchaseEventForOrder(order, req);
        }

        console.log(`✅ New order created: ${order.orderId} - ${country} - ${customer.name}`);

        res.status(201).json({
            success: true,
            orderId: order.orderId,
            repurchase: repurchaseContext ? {
                previousOrderId: repurchaseContext.previousOrderId,
                previousDeliveredAt: repurchaseContext.previousDeliveredAt
            } : null,
            purchase: purchase ? {
                ok: purchase.ok,
                alreadySent: purchase.alreadySent || false,
                eventId: purchase.result?.eventId || purchase.order?.tracking?.metaPurchaseEventId || '',
                response: purchase.result?.response || purchase.order?.tracking?.metaPurchaseResponse || null
            } : null,
            message: 'Order created successfully'
        });
    } catch (error) {
        console.error('Create order error:', error);
        res.status(500).json({ error: 'Failed to create order' });
    }
});

// PATCH /api/orders/:id - Update order status (authenticated)
router.patch('/:id', authMiddleware, (req, res, next) => {
    const action = manualHistoricalRequestV203({ method: req.method, path: req.originalUrl, body: req.body });
    if (!action) return next();
    if (req.user?.role !== 'admin' || String(req.user?._id || req.user?.id || '') === 'local-no-password') {
        return res.status(403).json({ success: false, error: 'manual_historical_authenticated_admin_required' });
    }
    req.body.status = action.status;
    if (String(process.env.VITALISMEN_EC_BOT_CORE_OPERATIONAL).toLowerCase() === 'true') {
        return ecPanelStatusAuthenticatedActionV177(req, res, next);
    }
    return next();
}, async (req, res) => {
    try {
        const { status, notes, trackingNumber, purchaseIntent, customer, delivery, package: packageData, total, productKey, productName, product } = req.body;
        const nextStatus = normalizeOrderStatus(status);

        const order = await Order.findOne({ orderId: req.params.id });

        if (!order) {
            return res.status(404).json({ error: 'Order not found' });
        }

        const requestedCustomerPhone = typeof customer?.phone === 'string' ? customer.phone : order.customer?.phone;
        const requestedCountry = typeof req.body.country === 'string' ? req.body.country : order.country;
        if (isBrazilTestOnly({ phone: requestedCustomerPhone, country: requestedCountry })) {
            return sendBrazilTestOnlyError(res);
        }

        const historicalAction = manualHistoricalRequestV203({ method: req.method, path: req.originalUrl, body: req.body });
        if (historicalAction) {
            if (order.country !== 'EC') return res.status(409).json({ success: false, error: 'manual_historical_ec_only' });
            const event = {
                version: 203, source: 'authenticated_operator', recordedAt: new Date().toISOString(),
                actorId: String(req.user._id || req.user.id), actor: req.user.email || req.user.name,
                orderId: order.orderId, phone: ecPhoneV203(order.customer?.phone), previousStatus: order.status, status: historicalAction.status,
                previousQuantity: order.package?.quantity, previousTotal: order.total,
                requestedQuantity: packageData?.quantity, requestedTotal: total,
                reason: typeof notes === 'string' ? notes : 'Atualizacao manual de historico; data efetiva da entrega/retorno nao informada.'
            };
            order.notes = appendAuditNote(order.notes, '[MANUAL_HISTORICAL_STATUS_V203] ' + JSON.stringify(event));
            order.manualHistoricalStatusV203 = event;
        } else if (typeof notes === 'string') order.notes = notes;
        if (trackingNumber) order.trackingNumber = trackingNumber;
        const hasRequestedProduct = Boolean(
            String(productKey || '').trim()
            || String(productName || '').trim()
            || String(product || '').trim()
        );
        const productSelection = hasRequestedProduct && isEcuadorCountry(order.country)
            ? strictEcuadorProductSelection({
                productKey,
                productName,
                product,
                packageLabel: packageData?.label
            })
            : null;
        if (productSelection && !productSelection.ok) {
            return sendExplicitProductError(res, productSelection);
        }
        const productInfo = productSelection?.product
            || (isEcuadorCountry(order.country) ? resolveEcuadorProductInfo(order) : null);
        if (productInfo?.key) {
            order.tracking = {
                ...(order.tracking || {}),
                ...productTrackingMetadata(productInfo)
            };
        }
        if (customer && typeof customer === 'object') {
            const allowedCustomerFields = ['name', 'phone', 'address', 'reference', 'city', 'province'];
            allowedCustomerFields.forEach((field) => {
                if (typeof customer[field] === 'string') {
                    order.customer[field] = customer[field].trim();
                }
            });
        }
        if (delivery && typeof delivery === 'object') {
            order.delivery = {
                ...(order.delivery?.toObject?.() || order.delivery || {}),
                ...(typeof delivery.mode === 'string' ? { mode: delivery.mode.trim() } : {}),
                ...(typeof delivery.agencyId === 'string' ? { agencyId: delivery.agencyId.trim() } : {}),
                ...(typeof delivery.agencyName === 'string' ? { agencyName: delivery.agencyName.trim() } : {})
            };
        }
        if (packageData && typeof packageData === 'object') {
            if (Object.prototype.hasOwnProperty.call(packageData, 'quantity')) {
                const normalizedQuantity = normalizePackageQuantity(packageData.quantity);
                order.package.quantity = normalizedQuantity;
                order.package.id = normalizedQuantity;
            }
            if (order.package.quantity) {
                order.package.label = productAwarePackageLabel({
                    country: order.country,
                    productInfo,
                    quantity: order.package.quantity,
                    fallback: typeof packageData.label === 'string' ? packageData.label.trim() : order.package.label
                });
            } else if (typeof packageData.label === 'string') {
                order.package.label = '';
            }
        }
        if (total !== undefined && total !== null && total !== '') {
            const parsedTotal = Number(total);
            if (Number.isFinite(parsedTotal) && parsedTotal >= 0) {
                order.total = parsedTotal;
            }
        }
        if (purchaseIntent) {
            order.purchaseIntent = {
                ...(order.purchaseIntent || {}),
                ...purchaseIntent
            };
        }

        const resolvedCustomerData = resolveOrderCustomerData({
            country: order.country,
            customer: order.customer,
            delivery: order.delivery,
            previousResolution: order.customerDataResolution?.toObject?.() || order.customerDataResolution || null,
            source: 'structured_form'
        });
        applyCustomerDataResolutionToOrder(order, resolvedCustomerData);

        if (nextStatus === 'confirmed') {
            if (resolvedCustomerData.resolution.orderDataReady !== true) {
                await order.save();
                return sendCustomerDataResolutionError(res, resolvedCustomerData.resolution);
            }
            try {
                await assertNoActiveDuplicateOrder({
                    phone: order.customer?.phone,
                    country: order.country,
                    currentOrderId: order.orderId
                });
            } catch (duplicateError) {
                return sendDuplicateOrderError(res, duplicateError);
            }
            const purchase = await markPurchaseEventForOrder(order, req);
            return res.json({
                ok: purchase.ok,
                success: purchase.ok,
                alreadySent: purchase.alreadySent || false,
                result: purchase.result,
                order: purchase.order,
                message: purchase.alreadySent
                    ? 'Order already confirmed'
                    : purchase.ok
                        ? 'Order confirmed and purchase event sent'
                        : 'Order confirmed, but purchase event failed'
            });
        }

        if (nextStatus) {
            const previousStatus = String(order.status || '').toLowerCase();
            order.status = nextStatus;
            if (nextStatus === 'confirmed' && previousStatus !== 'confirmed' && !order.confirmedAt) {
                order.confirmedAt = new Date();
            }
        }

        const statusPersistence = nextStatus && isEcuadorCountry(order.country)
            ? await persistManualPanelStatusV139({ order, panelStatus: nextStatus })
            : null;
        if (!statusPersistence) await order.save();
        let manualHistoricalPersistenceV203 = null;
        if (historicalAction) {
            const audit = order.manualHistoricalStatusV203;
            const contact = statusPersistence?.contactState;
            if (!contact || ecPhoneV203(contact.phoneDigits) !== ecPhoneV203(audit.phone)) throw new Error('manual_historical_contact_scope_invalid');
            contact.metadata = manualHistoricalMetadataV203(contact.metadata || {}, audit.toObject ? audit.toObject() : audit);
            contact.markModified('metadata');
            await contact.save();
            const shipment = await Shipment.findOne({ country: 'EC', orderId: order.orderId }).lean();
            const pause = manualShipmentTerminalReviewV203({ order, shipment, audit });
            if (pause) {
                await Shipment.updateOne(pause.filter, pause.update);
                if (!await Shipment.findOne({ ...pause.filter, 'review.manualOnly': true, 'review.reviewStatus': 'manual_terminal_recorded_v203' }).lean()) throw new Error('manual_historical_shipment_pause_not_persisted');
            }
            const verifiedOrder = await Order.findOne({ orderId: order.orderId, country: 'EC', status: historicalAction.status }).lean();
            const legacy = readEcLegacyHistoryV203(order.customer?.phone);
            const expected = historicalAction.status === 'delivered' ? 'entregue' : 'devolvido';
            const ledgerVerified = legacy.available && legacy.leads.some(row => row.status === expected);
            if (!verifiedOrder || !ledgerVerified || statusPersistence?.panel?.ok !== true) {
                return res.status(409).json({ success: false, error: 'manual_historical_read_after_write_failed', falseSuccessPrevented: true });
            }
            manualHistoricalPersistenceV203 = { orderVerified: true, ledgerVerified: true, shipmentNotificationsPaused: Boolean(pause), status: historicalAction.status };
        }

        res.json({
            success: true,
            order,
            ...(manualHistoricalPersistenceV203 ? { manualHistoricalPersistenceV203 } : {}),
            statusPersistence: statusPersistence ? {
                persistedInContactState: Boolean(statusPersistence.contactState),
                dropiCalled: false,
                postSaleTriggered: false
            } : null,
            message: 'Order updated'
        });
    } catch (error) {
        console.error('Update order error:', error);
        res.status(500).json({ error: 'Failed to update order' });
    }
});

// POST /api/orders/:id/confirm-payment - Confirm payment + send META Purchase (authenticated)
router.post('/:id/confirm-payment', authMiddleware, async (req, res) => {
