// POST /api/orders/draft - Create a new draft (public)
// Called when user enters phone + full name (2 names)
router.post('/draft', async (req, res) => {
    try {
        const {
            country,
            phone,
            name,
            delivery,
            tracking,
            productKey,
            productName,
            product
        } = req.body;

        if (!country || !phone || !name) {
            return res.status(400).json({ error: 'Country, phone and name are required' });
        }

        const resolvedCustomerData = resolveOrderCustomerData({
            country,
            customer: { phone, name },
            delivery,
            source: 'structured_form'
        });

        const requestedProductInput = { productKey, productName, product, tracking };
        const hasRequestedProduct = hasExplicitProductSelectionInput(requestedProductInput);
        const requestedProductSelection = hasRequestedProduct && isEcuadorCountry(country)
            ? strictEcuadorProductSelection(requestedProductInput)
            : null;
        if (requestedProductSelection && !requestedProductSelection.ok) {
            return sendExplicitProductError(res, requestedProductSelection);
        }
        const requestedProductMetadata = requestedProductSelection?.ok
            ? productTrackingMetadata(requestedProductSelection.product)
            : {};

        // Determine currency from country
        const currency = 'USD';

        // 1. Check if a DRAFT already exists for this phone
        // We match by the last 10 digits to be safe against format differences
        const phoneDigits = phone.replace(/\D/g, '').slice(-10);
        const existingDraft = await Order.findOne({
            country,
            status: 'draft',
            'customer.phone': { $regex: phoneDigits }
        }).sort({ createdAt: -1 });

        const duplicateGuard = await getOrderDuplicateGuard({
            phone,
            country,
            currentOrderId: existingDraft?.orderId || ''
        });
        if (!duplicateGuard.allowed) return sendDuplicateOrderError(res, duplicateGuard);

        if (existingDraft) {
            // Update the existing draft with latest name/formatting
            applyCustomerDataResolutionToOrder(existingDraft, resolveOrderCustomerData({
                country,
                customer: { ...(existingDraft.customer?.toObject?.() || existingDraft.customer || {}), phone, name },
                delivery: delivery || existingDraft.delivery,
                previousResolution: existingDraft.customerDataResolution?.toObject?.() || existingDraft.customerDataResolution || null,
                source: 'structured_form'
            }));
            existingDraft.updatedAt = new Date();

            if (tracking) {
                existingDraft.tracking = {
                    ...(existingDraft.tracking || {}),
                    ...(tracking || {}),
                    ...requestedProductMetadata,
                    ip: req.ip,
                    userAgent: req.get('user-agent') || ''
                };
            } else if (requestedProductSelection?.ok) {
                existingDraft.tracking = {
                    ...(existingDraft.tracking || {}),
                    ...requestedProductMetadata
                };
            }
