            .map((flag) => digitsOnly(flag._draftBridgeLead?.phone)).filter(Boolean))];
        const draftStates = draftPhones.length ? await ContactState.find({ $or: [
            { phoneDigits: { $in: draftPhones } },
            { chatId: { $in: draftPhones.map((phone) => `${phone}@c.us`) } }
