const getAdminLeadOperationalFlags = ({ ids = [] } = {}) => {
    const leadIds = Array.from(new Set((ids || [])
        .map((id) => Number.parseInt(String(id || '').trim(), 10))
        .filter((id) => Number.isFinite(id) && id > 0)))
        .slice(0, 3000);
    if (!leadIds.length) return {};

    const python = `
import sqlite3, json, re
db_path = "/opt/maxlien-mvp/leads_ec.sqlite3"
ids = ${JSON.stringify(leadIds)}
con = sqlite3.connect("file:" + db_path + "?mode=ro", uri=True)
con.row_factory = sqlite3.Row
cur = con.cursor()
cols = {row[1] for row in cur.execute("PRAGMA table_info(leads)").fetchall()}
wanted = [column for column in ["id", "phone", "status", "notes", "product_qty", "product_value", "name", "city", "province", "address", "country"] if column in cols]
flags = {}
if wanted:
    placeholders = ",".join(["?"] * len(ids))
    rows = cur.execute("SELECT " + ",".join(wanted) + " FROM leads WHERE id IN (" + placeholders + ")", ids).fetchall()
    marker_pattern = re.compile(
        r"\\[DROPI_PRODUCT\\]\\s*key=([^;\\r\\n]+);\\s*name=([^;\\r\\n]+);\\s*priceCatalog=([^;\\r\\n]+);\\s*quantity=(\\d+);\\s*total=([0-9.,]+)",
        re.IGNORECASE,
    )
    allowed_products = {"tex_ultra_ec", "nitrix_ec", "vit_power_ec"}
    allowed_catalogs = {"normal", "promotional"}
    for row in rows:
        data = dict(row)
        lead_id = str(data.get("id"))
        status = str(data.get("status") or "").strip().lower().replace("-", "_")
        notes = str(data.get("notes") or "")
        flag = {"status": status}
        phone_digits = re.sub(r"\D", "", str(data.get("phone") or ""))
        if len(phone_digits) >= 9:
            flag["_phoneTail"] = phone_digits[-9:]
        marker = marker_pattern.search(notes)
        if marker:
            product_key = marker.group(1).strip().lower()
            product_name = marker.group(2).strip()
            price_catalog = marker.group(3).strip().lower()
            quantity = int(marker.group(4))
            total = float(marker.group(5).replace(",", "."))
            if product_key in allowed_products and price_catalog in allowed_catalogs and quantity in (1, 2, 3, 6) and total > 0:
                product_selection = {
                    "productKey": product_key,
                    "productName": product_name,
                    "priceCatalog": price_catalog,
                    "quantity": quantity,
                    "total": total,
                }
                flag.update(product_selection)
                flag["productSelection"] = product_selection
        if status == "confirmado":
            flag["_draftBridgeLead"] = data
        flags[lead_id] = flag

lock_table_exists = cur.execute(
    "SELECT 1 FROM sqlite_master WHERE type='table' AND name='purchase_capi_lock'"
).fetchone()
if lock_table_exists:
    lock_cols = {row[1] for row in cur.execute("PRAGMA table_info(purchase_capi_lock)").fetchall()}
    required_lock_cols = {"lead_id", "status", "event_id", "response_payload", "error", "created_at", "updated_at"}
    if required_lock_cols.issubset(lock_cols):
        placeholders = ",".join(["?"] * len(ids))
        locks = cur.execute(
            "SELECT lead_id,status,event_id,response_payload,error,created_at,updated_at "
            "FROM purchase_capi_lock WHERE lead_id IN (" + placeholders + ")",
            ids,
        ).fetchall()
        for lock in locks:
            data = dict(lock)
            lead_id = str(data.get("lead_id"))
            flag = flags.setdefault(lead_id, {})
            response = {}
            try:
                response = json.loads(data.get("response_payload") or "{}")
            except Exception:
                response = {}
            if not isinstance(response, dict):
                response = {}
            lock_status = str(data.get("status") or "").strip().lower()
            lock_error = str(data.get("error") or "").strip()
            if lock_error and not response.get("error"):
                response["error"] = lock_error
            flag["metaPurchaseEventId"] = str(data.get("event_id") or "")
            flag["metaPurchaseResponse"] = response
            if lock_status == "sent":
                flag["metaPurchaseSentAt"] = data.get("updated_at") or data.get("created_at") or ""
print(json.dumps({"flags": flags}, ensure_ascii=False))
con.close()
`;

    const result = spawnSync('python3', ['-'], {
        input: python,
        encoding: 'utf8',
        maxBuffer: 2 * 1024 * 1024
    });
    if (result.status !== 0) {
        throw new Error(result.stderr || result.stdout || 'admin_lead_flags_failed');
    }
    const parsed = JSON.parse(result.stdout || '{"flags":{}}');
    return parsed.flags || {};
};

const createOperationalOrderFromAdminLead = async (requestedOrderId, lead) => {
