const deliveredOrderForAdminLead = async (lead = {}) => {
    const phoneDigits = String(lead.phone || '').replace(/\D/g, '');
    const tail = phoneDigits.slice(-9);
    if (!tail) return { order: null, shipment: null };
    const deliveredExternal = async () => {
        const external = await Shipment.find({ country: 'EC', 'client.phone': { $regex: tail + '$' },
            'logistics.status': 'ENTREGADO', 'outcomes.delivered': true,
            'raw.historicalExternalReconciliation.source': 'HISTORICAL_EXTERNAL_RECONCILIATION'
        }).sort({ 'automation.deliveredConfirmedAt': -1, updatedAt: -1 }).limit(5);
        const shipment = external.find(item => historicalExternalPostSaleEvidenceV140(item)
            && String(item.client?.phone || '').replace(/\D/g, '') === phoneDigits
            && Number.isFinite(new Date(item.automation?.deliveredConfirmedAt || '').getTime()));
        if (!shipment) return { order: null, shipment: null };
        // Immutable prior-sale view only. Do not create an old Order, invent a
        // commercial snapshot, replay Purchase or reuse this ID for the new sale.
        return { shipment, order: { orderId: shipment.orderId, country: 'EC', status: 'delivered',
            customer: { phone: shipment.client.phone }, tracking: {},
            deliveredAt: shipment.automation.deliveredConfirmedAt,
            shippingStatus: 'ENTREGADO' } };
    };
    const orders = await Order.find({
        country: 'EC',
        'customer.phone': { $regex: `${tail}$` }
    }).sort({ updatedAt: -1, createdAt: -1 }).limit(100);
    if (!orders.length) return deliveredExternal();
    const shipments = await Shipment.find({
        country: 'EC',
        orderId: { $in: orders.map((order) => order.orderId).filter(Boolean) }
    }).sort({ 'logistics.lastStatusAt': -1, updatedAt: -1, createdAt: -1 });
    const shipmentByOrderId = new Map();
    for (const shipment of shipments) {
        if (!shipmentByOrderId.has(shipment.orderId)) shipmentByOrderId.set(shipment.orderId, shipment);
    }
    const order = orders.find((candidate) => panelOrderLifecycle({
        order: candidate,
        shipment: shipmentByOrderId.get(candidate.orderId) || null
    }).delivered) || null;
    if (!order) return deliveredExternal();
    return {
        order,
        shipment: shipmentByOrderId.get(order.orderId) || null
    };
};

const stagedOrderDataFromAdminLead = ({ lead = {}, state = null, previousOrder = null } = {}) => {
    const draft = state?.metadata?.customerDraft?.toObject?.()
        || state?.metadata?.customerDraft
        || {};
    const customerDataResolution = state?.customerDataResolution?.toObject?.()
        || state?.customerDataResolution
        || {};
    assertCustomerOrderDataReady(customerDataResolution);
    const quantity = normalizePackageQuantity(lead.product_qty || draft.quantity);
    const total = parseMoney(lead.product_value || draft.total, 0);
    if (!quantity || total <= 0) {
        const error = new Error('Quantidade e valor positivos sao obrigatorios para registrar a recompra.');
        error.status = 422;
        error.code = 'repurchase_quantity_total_required';
        throw error;
    }
    const productInfo = resolveEcuadorProductInfo(
        draft,
        previousOrder,
        lead.notes,
        lead.event_source_url,
        lead.utm_campaign,
        lead.utm_content
    );
    if (!productInfo?.key) {
        const error = new Error('Produto EC explicito obrigatorio para registrar a recompra.');
        error.status = 422;
        error.code = 'repurchase_explicit_product_required';
        throw error;
    }
    const phone = String(draft.phone || lead.phone || '').trim();
    const phoneDigits = phone.replace(/\D/g, '');
    const customer = {
        name: String(draft.name || lead.name || '').trim(),
        phone: phoneDigits ? `+${phoneDigits}` : phone,
        address: String(draft.address || lead.address || '').trim(),
        reference: String(draft.reference || '').trim(),
        city: String(draft.city || lead.city || '').trim(),
        province: String(draft.province || lead.province || '').trim()
    };
    const delivery = {
        mode: String(draft.deliveryMode || '').trim(),
        agencyId: String(draft.agencyId || '').trim(),
        agencyName: String(draft.agencyName || '').trim()
    };
    const missing = [
        ['nome', customer.name],
        ['telefone', customer.phone],
        ['endereco', customer.address],
        ['cidade', customer.city],
        ['provincia', customer.province]
    ].filter(([, value]) => !value).map(([field]) => field);
    if (missing.length) {
        const error = new Error(`Complete antes de registrar a recompra: ${missing.join(', ')}`);
        error.status = 422;
        error.code = 'repurchase_customer_data_required';
        throw error;
    }
    return {
        draft,
        customerDataResolution,
        quantity,
        total,
        productInfo,
        customer,
        delivery,
        tracking: {
            ...((state?.metadata?.tracking?.toObject?.() || state?.metadata?.tracking) || {}),
            productSelectionSource: 'manual_customer_draft',
            ...ecuadorProductMetadata(productInfo)
        }
    };
};

const ensurePurchaseForStagedOrder = async ({ order, req, sourceOrderId }) => {
    if (integrationPolicyV254()) return queuedPurchaseResponseV254(order);
    if (order.tracking?.metaPurchaseSentAt) {
        return {
            ok: true,
            skipped: true,
            alreadySent: true,
            eventId: order.tracking?.metaPurchaseEventId || order.orderId,
            response: order.tracking?.metaPurchaseResponse || null,
            sentAt: order.tracking?.metaPurchaseSentAt
        };
    }
    const purchase = await sendPurchaseEventForOrder(order);
    order.tracking = order.tracking || {};
    order.tracking.metaPurchaseEventId = purchase.eventId || order.orderId;
    if (purchase.ok) {
        order.tracking.metaPurchaseSentAt = new Date();
        order.tracking.metaPurchaseResponse = purchase.response;
    } else {
        order.tracking.metaPurchaseResponse = {
            ok: false,
            status: purchase.status,
            data: purchase.data,
            error: purchase.error
        };
    }
    await order.save();
    if (order.tracking?.metaPurchaseSentAt) {
        recordOnlineAdminPurchaseLock({
            order,
            purchase,
            sourceOrderId,
            country: 'EC'
        });
    }
    return purchase;
};

export const ensurePurchaseAfterHumanDropiSuccessV141 = async ({
    order,
    shipment,
    dropiResult,
    freshDropiSubmission = false,
    sourceOrderId = '',
    purchaseSender = sendPurchaseEventForOrder,
    purchaseLock = recordOnlineAdminPurchaseLock,
    persistOrder = async (target) => target.save()
} = {}) => {
    if (integrationPolicyV254()) return queuedPurchaseResponseV254(order);
    const dropiSucceeded = dropiResult?.ok === true || dropiResult?.success === true;
    if (!dropiSucceeded) return { ok: false, skipped: true, reason: 'dropi_not_successful' };
    if (freshDropiSubmission !== true) {
        return { ok: false, skipped: true, reason: 'historical_or_existing_dropi_submission' };
    }
    if (!shipment?.automation?.dropiSubmitAuthorizedAt) {
        return { ok: false, skipped: true, reason: 'human_dropi_authorization_missing' };
    }
    if (!order) return { ok: false, skipped: true, reason: 'order_missing' };
    if (order.tracking?.metaPurchaseSentAt) {
        return {
            ok: true,
            skipped: true,
            alreadySent: true,
            eventId: order.tracking?.metaPurchaseEventId || order.orderId
        };
    }
    try {
        const purchase = await purchaseSender(order);
        order.tracking = order.tracking || {};
        order.tracking.metaPurchaseEventId = purchase.eventId || order.orderId;
        const metaAccepted = purchase.ok === true
            && Number(purchase.response?.events_received || 0) > 0;
        if (metaAccepted) {
            order.tracking.metaPurchaseSentAt = new Date();
            order.tracking.metaPurchaseResponse = purchase.response;
        } else {
            order.tracking.metaPurchaseResponse = {
                ok: false,
                status: purchase.status,
                data: purchase.data,
                response: purchase.response,
                error: purchase.error || 'meta_purchase_not_accepted'
            };
        }
        await persistOrder(order);
        if (order.tracking.metaPurchaseSentAt) {
            purchaseLock({
                order,
                purchase,
                sourceOrderId: sourceOrderId || order.orderId,
                country: 'EC'
            });
        }
        return {
            ok: metaAccepted,
            skipped: false,
            eventId: order.tracking.metaPurchaseEventId,
            metaAccepted,
            error: metaAccepted ? '' : String(purchase.error || 'meta_purchase_not_accepted')
        };
    } catch (error) {
        return { ok: false, skipped: false, reason: 'meta_purchase_pipeline_failed', error: error.message };
    }
};

const stageConfirmedAdminLeadOrder = async ({ leadId, forceRepurchase = false, note = '', req }) => {
    const adminOrderId = `EC-ADMIN-${leadId}`;
    const correlationId = `panel-confirm-${Date.now()}-${crypto.randomBytes(4).toString('hex')}`;
    const requestedBy = req?.user?.email || req?.user?.name || 'panel';
    const lead = getAdminLeadSnapshot({ orderId: adminOrderId });
    if (!lead) {
        const error = new Error('Lead EC nao encontrado.');
        error.status = 404;
        error.code = 'admin_lead_not_found';
        throw error;
    }
    if (String(lead.country || 'EC').trim().toUpperCase() !== 'EC') {
        const error = new Error('Registro de recompra liberado somente para Equador.');
        error.status = 400;
        error.code = 'repurchase_ec_only';
        throw error;
    }

    if (integrationPolicyV254() && /^v254:lead:\d+:\d+$/.test(req?.integrationIntakeV254?.key || '')) {
        if (lead.status !== 'confirmado') throw Object.assign(new Error('A confirmacao deste lead foi substituida.'), { status:409, code:'confirmation_superseded' });
        lead._integrationIntakeKeyV254 = req.integrationIntakeV254.key;
        lead._integrationOccurredAtV254=req.integrationIntakeV254.occurredAt;
    }
    const state = await findContactStateForAdminLead(lead);
    const historical = await deliveredOrderForAdminLead(lead);
    const mustCreateRepurchase = Boolean(
        forceRepurchase
        || ['entregue', 'recompra'].includes(String(lead.status || '').trim().toLowerCase())
        || historical.order
    );
    if (!mustCreateRepurchase) {
        let order = await findCurrentOrderForAdminLead(adminOrderId);
        if (!order) order = await createOperationalOrderFromAdminLead(adminOrderId, { ...lead, status: 'confirmado' });
        if (!order) {
            const error = new Error('Lead precisa estar completo antes de entrar em Pedidos Confirmados.');
            error.status = 422;
            error.code = 'confirmed_order_data_required';
            throw error;
        }
        if (!['draft', 'pending', 'confirmed'].includes(String(order.status || '').trim().toLowerCase())) {
            const error = new Error(`O pedido operacional ${order.orderId} ja avancou para ${order.status} e nao pode ser rebaixado para confirmado.`);
            error.status = 409;
            error.code = 'confirmed_order_already_advanced';
            throw error;
        }
        order.status = 'confirmed';
        if (!order.confirmedAt) order.confirmedAt = new Date();
        await order.save();
        const confirmedPersistence = persistConfirmedOrderToOnlineAdminPanelV158(order, {
            action: 'admin_lead_stage_confirmed_v158',
            leadId,
            requestedBy,
            correlationId
        });
        if (!confirmedPersistence.ok) {
            const error = new Error('O pedido foi preservado, mas a lista Confirmados nao comprovou a persistencia. Nenhum sucesso foi declarado.');
            error.status = confirmedPersistence.reason === 'lead_not_found' ? 404 : 409;
            error.code = confirmedPersistence.reason || 'confirmed_panel_persistence_failed';
            error.confirmedPersistence = confirmedPersistence;
            throw error;
        }
        let contactStateVerified = !state;
        if (state) {
            const currentDraft = state.metadata?.customerDraft?.toObject?.()
                || state.metadata?.customerDraft
                || {};
            state.metadata = {
                ...(state.metadata || {}),
                customerDraft: {
                    ...currentDraft,
                    orderId: order.orderId,
                    sourceOrderId: adminOrderId,
                    previousOrderId: order.previousOrderId || '',
                    currentNegotiationOrderId: order.orderId,
                    status: 'confirmado',
                    updatedAt: new Date().toISOString()
                }
            };
            state.markModified('metadata');
            await state.save();
            const finalState = await ContactState.findById(state._id).select('metadata.customerDraft').lean();
            contactStateVerified = Boolean(
                finalState?.metadata?.customerDraft?.orderId === order.orderId
                && finalState?.metadata?.customerDraft?.status === 'confirmado'
            );
            if (!contactStateVerified) {
                const error = new Error('A leitura final da ficha nao comprovou o pedido confirmado. Nenhum sucesso foi declarado.');
                error.status = 409;
                error.code = 'confirmed_contact_state_read_after_write_failed';
                error.confirmedPersistence = confirmedPersistence;
                throw error;
            }
        }
        return {
            order,
            repurchase: false,
            reused: Boolean(order._mappedFromAdminLead),
            previousOrderId: '',
            confirmedPersistence,
            contactStateVerified
        };
    }
    if (!historical.order) {
        const error = new Error('Pedido anterior entregue nao encontrado para registrar a recompra.');
        error.status = 409;
        error.code = 'previous_order_not_delivered';
        throw error;
    }

    const prepared = stagedOrderDataFromAdminLead({
        lead,
        state,
        previousOrder: historical.order
    });
    const phoneTail = prepared.customer.phone.replace(/\D/g, '').slice(-9);
    const activeRepurchase = await Order.findOne({
        country: 'EC',
        previousOrderId: historical.order.orderId,
        entryReason: 'repeat_purchase_after_delivered',
        status: { $in: activeRepurchaseStatuses },
        'customer.phone': { $regex: `${phoneTail}$` }
    }).sort({ updatedAt: -1, createdAt: -1 });
    const decision = deliveredRepurchaseRegistrationDecision({
        authenticated: Boolean(req?.user),
        currentOrder: historical.order,
        currentShipment: historical.shipment,
        activeRepurchase,
        newCustomerPhone: prepared.customer.phone
    });
    if (!decision.allowed) {
        const error = new Error(decision.reason || 'repurchase_registration_not_allowed');
        error.status = decision.statusCode || 409;
        error.code = decision.reason || 'repurchase_registration_not_allowed';
        throw error;
    }

    const order = decision.reused
        ? activeRepurchase
        : new Order({ orderId: decision.orderId, ...(lead._integrationIntakeKeyV254 ? { integrationIntakeKeyV254: lead._integrationIntakeKeyV254, confirmedAt:new Date(lead._integrationOccurredAtV254) } : {}) });
    const canRefresh = !decision.reused || ['draft', 'pending', 'confirmed'].includes(String(order.status || ''));
    if (canRefresh) {
        order.country = 'EC';
        order.customer = prepared.customer;
        order.delivery = prepared.delivery;
        order.customerDataResolution = prepared.customerDataResolution;
        order.package = {
            id: prepared.quantity,
            label: ecuadorPackageLabel(prepared.productInfo, prepared.quantity),
            quantity: prepared.quantity
        };
        order.total = prepared.total;
        order.currency = 'USD';
        order.status = 'confirmed';
        order.source = 'manual';
        order.entryReason = decision.entryReason;
        order.previousOrderId = decision.previousOrderId;
        order.previousDeliveredAt = decision.previousDeliveredAt;
        order.purchaseIntent = {
            ...(order.purchaseIntent?.toObject?.() || order.purchaseIntent || {}),
            readiness: 'ready_now',
            requestedQuantity: prepared.quantity,
            requestedPackageLabel: ecuadorPackageLabel(prepared.productInfo, prepared.quantity),
            readyConfirmedAt: order.purchaseIntent?.readyConfirmedAt || new Date()
        };
        order.notes = order.notes || appendAuditNote(
            '',
            `Recompra registrada a partir do lead EC ${leadId}; pedido anterior ${decision.previousOrderId}.${note ? ` ${note}` : ''}`
        );
        order.tracking = {
            ...(order.tracking?.toObject?.() || order.tracking || {}),
            ...prepared.tracking
        };
        await order.save();
    }
    if (state) {
        state.metadata = {
            ...(state.metadata || {}),
            customerDraft: {
                ...(prepared.draft || {}),
                orderId: order.orderId,
                sourceOrderId: prepared.draft.sourceOrderId || historical.order.orderId,
                previousOrderId: decision.previousOrderId,
                currentNegotiationOrderId: order.orderId,
                status: 'confirmado',
                product: prepared.productInfo.name,
                productName: prepared.productInfo.name,
                productKey: prepared.productInfo.key,
                updatedAt: new Date().toISOString()
            }
        };
        state.markModified('metadata');
        await state.save();
    }
    const confirmedPersistence = persistConfirmedOrderToOnlineAdminPanelV158(order, {
        action: 'admin_lead_stage_repurchase_confirmed_v158',
        leadId,
        requestedBy,
        correlationId
    });
    if (!confirmedPersistence.ok) {
        const error = new Error('A recompra foi preservada no Mongo, mas a lista Confirmados nao comprovou a persistencia. Nenhum sucesso foi declarado.');
        error.status = confirmedPersistence.reason === 'lead_not_found' ? 404 : 409;
        error.code = confirmedPersistence.reason || 'confirmed_panel_persistence_failed';
        error.confirmedPersistence = confirmedPersistence;
        throw error;
    }
    let contactStateVerified = !state;
    if (state) {
        const finalState = await ContactState.findById(state._id).select('metadata.customerDraft').lean();
        contactStateVerified = Boolean(
            finalState?.metadata?.customerDraft?.orderId === order.orderId
            && finalState?.metadata?.customerDraft?.status === 'confirmado'
        );
        if (!contactStateVerified) {
            const error = new Error('A leitura final da ficha da recompra nao comprovou o pedido confirmado. Nenhum sucesso foi declarado.');
            error.status = 409;
            error.code = 'confirmed_contact_state_read_after_write_failed';
            error.confirmedPersistence = confirmedPersistence;
            throw error;
        }
    }
    const purchase = order.tracking?.metaPurchaseSentAt
        ? {
            ok: true,
            skipped: true,
            alreadySent: true,
            eventId: order.tracking.metaPurchaseEventId || order.orderId
        }
        : { ok: false, skipped: true, reason: 'awaiting_dropi' };
    return {
        order,
        purchase,
        repurchase: true,
        reused: decision.reused,
        previousOrderId: decision.previousOrderId,
        confirmedPersistence,
        contactStateVerified
    };
};

