const buildDropiSubmitStatus = ({ order, shipment, orderId }) => {
    const targetOrderId = order?.orderId || shipment?.orderId || orderId;
    const alreadySubmitted = alreadySubmittedResponse(order, shipment);
    if (alreadySubmitted) {
        return {
            ...alreadySubmitted,
            status: 'submitted',
            processing: false,
            orderStatus: order?.status || '',
            reviewStatus: shipment?.review?.reviewStatus || '',
            checkpoint: shipment?.automation?.browserCheckpoint || '',
            lastError: integrationPolicyV254() ? '' : shipment?.automation?.browserLastError || ''
        };
    }

    const reviewStatus = shipment?.review?.reviewStatus || '';
    const checkpoint = shipment?.automation?.browserCheckpoint || '';
    const lastError = shipment?.automation?.browserLastError || '';
    const active = targetOrderId ? activeDropiSubmitJobs.has(targetOrderId) : false;
    const running = active
        || reviewStatus === 'dropi_submit_running'
        || checkpoint === 'dropi_submit_queued'
        || checkpoint === 'dropi_submit_locked_waiting';

    if (running) {
        return {
            ok: true,
            success: true,
            status: 'processing',
            processing: true,
            submitQueued: true,
            shipment,
            orderStatus: order?.status || '',
            reviewStatus,
            checkpoint,
            lastError,
            message: 'Envio Dropi ainda esta processando.'
        };
    }

    if (reviewStatus === 'dropi_payment_required' || checkpoint === 'dropi_payment_required') {
        return {
            ok: false,
            success: false,
            status: 'payment_required',
            paymentRequired: true,
            shipment,
            orderStatus: order?.status || '',
            reviewStatus,
            checkpoint,
            lastError,
            message: 'Dropi chegou ate o envio, mas bloqueou por saldo/credito insuficiente.'
        };
    }

    if(integrationPolicyV254()&&order?.dropiDispatchV252?.version===254&&order.dropiDispatchV252.reason==='awaiting_customer_data_v254')return {ok:false,status:'awaiting_data',processing:false,manualSendRequired:false,orderId:targetOrderId,reason:'saved_delivery_data_required',message:'Compra confirmada; complete os dados de entrega na ficha para envio automatico.'};
    if (integrationPolicyV254() && shipment?.raw?.fulfillmentRecoveryV254) {
        const r = shipment.raw.fulfillmentRecoveryV254;
        return { ok:false, success:false, status:r.state, processing:['awaiting_session','retry_wait','dispatch_claimed','verifying_confirmation'].includes(r.state), manualSendRequired:false, recoveryState:r.state,
            shipment, orderStatus:order?.status || '', reviewStatus, checkpoint, lastError, message:r.label || lastError };
    }
    if (shipment?.review?.manualOnly || reviewStatus === 'manual_send_required') {
        return {
            ok: false,
            success: false,
            status: 'manual_required',
            manualSendRequired: true,
            shipment,
            orderStatus: order?.status || '',
            reviewStatus,
            checkpoint,
            lastError,
            reason: shipment?.review?.reviewReason || 'manual_send_required',
            error: lastError,
            message: describeDropiSubmitFailure(lastError || shipment?.review?.reviewReason)
        };
    }

    if (!isAuthorizedForDropiSubmit(shipment)) {
        return {
            ok: false,
            success: false,
            status: 'authorization_required',
            authorizationRequired: true,
            shipment,
            orderStatus: order?.status || '',
            reviewStatus,
            checkpoint,
            lastError,
            message: 'Pedido ainda nao foi autorizado para envio na Dropi.'
        };
    }

    return {
        ok: true,
        success: true,
        status: 'authorized',
        processing: false,
        shipment,
        orderStatus: order?.status || '',
        reviewStatus,
        checkpoint,
        lastError,
        message: 'Pedido autorizado e aguardando envio.'
    };
};

