            payload: {
                reason: req.body?.reason || 'operator_requeue',
                targetStage: 'send_to_dropi',
                requestedBy: req.user?.email || req.user?.name || ''
            }
        });
        shipment.events = shipment.events.slice(-60);
        await shipment.save();

        res.json({
